public class UseCompoundDrawableDetector extends LayoutDetector {
    public static final Issue ISSUE = Issue.create(
        "UseCompoundDrawables",
        "Node can be replaced by a `TextView` with compound drawables",
        "...",
        Category.PERFORMANCE, 5, Severity.WARNING,
        new Implementation(UseCompoundDrawableDetector.class, Scope.RESOURCE_FILE_SCOPE));

    @Override
    public Collection<String> getApplicableElements() { return Arrays.asList(LINEAR_LAYOUT); }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (!element.getTagName().equals(LINEAR_LAYOUT)) return;

        List<Element> children = Lint.getChildren(element);
        if (children.size() != 2) return;

        Element image = null;
        Element text = null;
        for (Element child : children) {
            String tag = child.getTagName();
            if (tag.equals(IMAGE_VIEW)) image = child;
            else if (tag.equals(TEXT_VIEW)) text = child;
        }
        if (image == null || text == null) return;

        String src = image.getAttributeNS(ANDROID_URI, ATTR_SRC);
        if (src == null || src.isEmpty()) return;

        String orientation = element.getAttributeNS(ANDROID_URI, ATTR_ORIENTATION);
        boolean vertical = VALUE_VERTICAL.equals(orientation);

        String attr;
        if (vertical) {
            attr = children.get(0) == image ? "android:drawableTop" : "android:drawableBottom";
        } else {
            attr = children.get(0) == image ? "android:drawableLeft" : "android:drawableRight";
        }
        context.report(ISSUE, element, context.getLocation(element),
            String.format("This tag and its children can be replaced by a single `<TextView/>` " +
                "and a compound drawable"));
    }
}
```
